def deep_copy(value):
    if isinstance(value, dict):
        return {key: deep_copy(item) for key, item in value.items()}
    if isinstance(value, list):
        return [deep_copy(item) for item in value]
    return value

def expand_case(fixture_inputs, case_input):
    if case_input.get("base_ref") != "portfolio":
        raise ValueError("未定義base_ref")
    expanded = deep_copy(fixture_inputs["portfolio"])
    for replacement in case_input["replacements"]:
        path = replacement["path"]
        if not path:
            raise ValueError("空path")
        cursor = expanded
        for member in path[:-1]:
            if not isinstance(cursor, dict) or member not in cursor:
                raise ValueError("未定義path")
            cursor = cursor[member]
        if not isinstance(cursor, dict) or path[-1] not in cursor:
            raise ValueError("未定義終端")
        cursor[path[-1]] = deep_copy(replacement["value"])
    return expanded

def route_failure(findings, return_owner):
    unique = {(item['code'], item['pointer'], return_owner) for item in findings}
    ordered = sorted(unique)
    return [{'code': code, 'pointer': pointer, 'return_owner': owner} for code, pointer, owner in ordered]

def compare_node_material(project, node, actual, context, diagnostic_contract, declared, context_project):
    rules=diagnostic_contract
    return_owner='portfolio-trace-owner'
    facets=rules['facet_order']
    source_fields=rules['source_fields']
    receipt_fields=rules['receipt_fields']
    axes=rules['state_axes']
    def as_map(value):
        return value if isinstance(value,dict) else {}
    def known(value):
        return isinstance(value,str) and len(value)>0
    def pointer(side,project,node,*parts):
        prefix='/projects/' if side=='actual' else '/context/projects/'
        return prefix+str(project).replace('~','~0').replace('/','~1')+'/'+str(node).replace('~','~0').replace('/','~1')+''.join('/'+str(part).replace('~','~0').replace('/','~1') for part in parts)
    def classify_set(value,ptr,allow_empty):
        if not isinstance(value,list) or any(not known(item) for item in value) or len(set(value))!=len(value):
            return None
        if not value and not allow_empty:
            return None
        return set(value)
    result={f:'corresponding' for f in facets}
    local_findings=[]
    def add(code, ptr):
        local_findings.append({'code':code,'pointer':ptr,'return_owner':return_owner})
    def compare_string(a,b,pa,pb):
        a_known=known(a); b_known=known(b)
        if not a_known: add('field_unknown',pa)
        if not b_known: add('field_unknown',pb)
        if not a_known or not b_known: return 'unknown'
        if a != b:
            add('field_conflict',pa); return 'violation'
        return 'corresponding'
    def mark(f, disp):
        rank={'corresponding':0,'unknown':1,'violation':2}
        if rank[disp]>rank[result[f]]: result[f]=disp
    ap=pointer('actual',project,node); cp=pointer('context',project,node)
    for field in source_fields:
        d=compare_string(as_map(actual.get('source')).get(field),as_map(context.get('source')).get(field),ap+'/source/'+field,cp+'/source/'+field)
        mark('source',d)
    ak=as_map(actual.get('source')).get('kind'); ck=as_map(context.get('source')).get('kind')
    for value,side in [(ak,'actual'),(ck,'context')]:
        if not isinstance(value,str) or value not in {'unit','connection','composite'}:
            add('kind_unknown',pointer(side,project,node,'source','kind')); mark('source','unknown')
        elif isinstance(declared,str) and declared in {'unit','connection','composite'} and value != declared:
            add('kind_conflict',pointer(side,project,node,'source','kind')); mark('source','violation')
    # R03: 各sideのowner集合を分類し、既知集合同士は件数に関わらず集合差を比較する。
    owners=[]
    for obj,side in [(actual,'actual'),(context,'context')]:
        val=obj.get('owners'); p=pointer(side,project,node,'owners')
        s=classify_set(val,p,False)
        if s is None:
            add('owner_unknown',p); mark('owner','unknown'); owners.append(None)
        elif len(s)>1:
            add('owner_ambiguous',p); mark('owner','violation'); owners.append(s)
        else: owners.append(s)
    if owners[0] is not None and owners[1] is not None and owners[0]!=owners[1]:
        add('owner_conflict',ap+'/owners');mark('owner','violation')
    # R04 relation sets and context-side endpoint existence.
    relations=[]
    for obj,side in [(actual,'actual'),(context,'context')]:
        val=obj.get('relations'); p=pointer(side,project,node,'relations')
        # R04のrelation domainをR12のselector資格と分離する。selector値は補完しない。
        selector_kind_known=isinstance(declared,str) and declared in {'unit','connection','composite'}
        relation_unit=declared=='unit' if selector_kind_known else as_map(obj.get('source')).get('kind')=='unit'
        s=classify_set(val,p,relation_unit)
        if s is None:
            add('relation_unknown',p);mark('relation','unknown');relations.append(None)
        else: relations.append(s)
    if relations[0] is not None and relations[1] is not None and relations[0]!=relations[1]:
        add('relation_conflict',ap+'/relations');mark('relation','violation')
    for obj,side in [(actual,'actual'),(context,'context')]:
        rel=obj.get('relations')
        rel_ptr=pointer(side,project,node,'relations')
        if isinstance(rel,list) and all(known(x) for x in rel) and len(set(rel))==len(rel):
            rendered={}
            # L4のtarget_id@target_revision表記が一意に解ける文脈nodeだけをendpoint候補にする。
            portfolio=context_project
            for other in portfolio.values():
                src=as_map(other).get('source',{}); src=as_map(src); tid=src.get('target_id'); rev=src.get('target_revision')
                if not known(tid) or not known(rev):
                    continue
                elif '@' in tid or '@' in rev:
                    rendered.setdefault(tid+'@'+rev,[]).append((tid,rev,'ambiguous_encoding'))
                else:
                    rendered.setdefault(tid+'@'+rev,[]).append((tid,rev,'unique'))
            unresolved=False; missing=False
            for endpoint in rel:
                candidates=rendered.get(endpoint,[])
                identities={(row[0],row[1]) for row in candidates}
                if len(identities)>1 or any(row[2]=='ambiguous_encoding' for row in candidates):
                    unresolved=True
                elif not candidates:
                    missing=True
            if unresolved:
                add('relation_unknown',rel_ptr);mark('relation','unknown')
            if missing:
                add('relation_endpoint_conflict',rel_ptr);mark('relation','violation')
    # R05 states and state source references.
    for axis,allowed in axes.items():
        aa=as_map(as_map(actual.get('states')).get(axis)); cc=as_map(as_map(context.get('states')).get(axis))
        av=aa.get('state'); cv=cc.get('state'); pa=ap+'/states/'+axis+'/state'; pc=cp+'/states/'+axis+'/state'
        if av not in allowed:
            add('state_unknown',pa);mark('state','unknown')
        if cv not in allowed:
            add('state_unknown',pc);mark('state','unknown')
        if av in allowed and cv in allowed and av!=cv:
            add('state_conflict',pa);mark('state','violation')
        for key in ['source_ref','source_revision']:
            d=compare_string(aa.get(key),cc.get(key),ap+'/states/'+axis+'/'+key,cp+'/states/'+axis+'/'+key);mark('state',d)
    av=as_map(as_map(actual.get('states')).get('knowledge')).get('state')
    if av=='unknown': add('knowledge_unknown',ap+'/states/knowledge/state');mark('state','unknown')
    av=as_map(as_map(actual.get('states')).get('freshness')).get('state')
    if av=='stale': add('state_stale',ap+'/states/freshness/state');mark('state','unknown')
    # R06 receipt/result states and field joins.
    for facet in ['verification','acceptance','provision']:
        ar=as_map(actual.get(facet)); cr=as_map(context.get(facet))
        allowed=rules['result_states'][facet]
        ast=ar.get('state'); cst=cr.get('state'); p=ap+'/'+facet+'/state'; q=cp+'/'+facet+'/state'
        if ast not in allowed:
            add('result_unknown',p);mark(facet,'unknown')
        if cst not in allowed:
            add('result_unknown',q);mark(facet,'unknown')
        if ast in allowed and cst in allowed and ast!=cst:
            add('result_conflict',p);mark(facet,'violation')
        # Receipt identity fields bind against context receipt and node source.
        for field in receipt_fields:
            d=compare_string(ar.get(field),cr.get(field),ap+'/'+facet+'/'+field,cp+'/'+facet+'/'+field);mark(facet,d)
            if field in ['project_id','requirement_revision','scope','target_id','target_revision','kind']:
                expected=as_map(context.get('source')).get(field)
                if not known(expected):
                    mark(facet,'unknown')
                elif known(ar.get(field)) and ar.get(field)!=expected:
                    add('field_conflict',ap+'/'+facet+'/'+field);mark(facet,'violation')
        if facet=='provision':
            for field in rules['provision_additional_comparison_fields']:
                d=compare_string(ar.get(field),cr.get(field),ap+'/'+facet+'/'+field,cp+'/'+facet+'/'+field)
                mark(facet,d)
    if as_map(actual.get('verification')).get('state')=='pass_material' and as_map(as_map(actual.get('states')).get('verification')).get('state')=='not_verified':
        add('verification_state_conflict',ap+'/verification/state');mark('verification','violation')
    if as_map(actual.get('provision')).get('state')=='provided_material' and as_map(as_map(actual.get('states')).get('provision')).get('state')=='not_provided':
        add('provision_state_conflict',ap+'/provision/state');mark('provision','violation')
    # R08 history sets; context entries may not be erased.
    for field in ['unresolved_edges','stale_reasons']:
        av=actual.get(field);cv=context.get(field);pa=ap+'/'+field;pc=cp+'/'+field
        aset=classify_set(av,pa,True);cset=classify_set(cv,pc,True)
        if aset is None: add('history_unknown',pa);mark('history','unknown')
        if cset is None: add('history_unknown',pc);mark('history','unknown')
        if aset is not None and cset is not None and not cset.issubset(aset): add('history_lost',pa);mark('history','violation')
    if as_map(as_map(actual.get('states')).get('freshness')).get('state')=='stale' and actual.get('stale_reasons')==[]:
        add('stale_reason_missing',ap+'/stale_reasons');mark('history','unknown')
    # R09 boundary claims are checked on actual source only.
    for field in ['from_unit_success','from_pr_ci_plan','whole_node_complete']:
        value=as_map(actual.get('claims')).get(field);p=ap+'/claims/'+field
        if value is True: add('inferred_completion_forbidden',p);mark('boundary','violation')
        elif value is not False: add('claim_unknown',p);mark('boundary','unknown')
    return {'facet_results':result,'findings':local_findings}

def evaluate_portfolio(input, diagnostic_contract, *selected_targets):
    if len(selected_targets)==1:
        return evaluate_portfolio_selected(input,diagnostic_contract,selected_targets[0])
    if len(selected_targets)>1:
        raise ValueError('evaluate_portfolio引数個数不正')
    data = input
    rules = diagnostic_contract
    return_owner = 'portfolio-trace-owner'
    compatibility=rules.get('baseline_fixture_compatibility',{})
    projects = rules.get('projects',compatibility.get('projects'))
    nodes = rules.get('node_kinds',compatibility.get('node_kinds'))
    axes = rules['state_axes']
    facets = rules['facet_order']
    source_fields = rules['source_fields']
    receipt_fields = rules['receipt_fields']
    node_corr = {}
    retained_source = {}
    retained_state = {}
    gaps = {}
    findings = []
    def pointer(side, project, node, *parts):
        prefix = '/projects/' if side == 'actual' else '/context/projects/'
        return prefix + project + '/' + node + ''.join('/' + str(p).replace('~','~0').replace('/','~1') for p in parts)
    def add(code, ptr):
        findings.append({'code':code,'pointer':ptr,'return_owner':return_owner})
    def known(v):
        return isinstance(v,str) and len(v)>0
    def classify_set(value, ptr, allow_empty):
        if not isinstance(value,list) or any(not known(x) for x in value) or len(set(value)) != len(value):
            return None
        if not value and not allow_empty:
            return None
        return set(value)
    def compare_node(project, node, actual, context):
        return compare_node_material(project,node,actual,context,rules,nodes[node],data['context']['projects'][project])
    for project in projects:
        node_corr[project]={};retained_source[project]={};retained_state[project]={};gaps[project]={}
        for node in nodes:
            a=data['projects'][project][node];c=data['context']['projects'][project][node]
            compared=compare_node(project,node,a,c)
            node_corr[project][node]=compared['facet_results']
            for finding in compared['findings']: findings.append(finding)
            retained_source[project][node]=deep_copy(a['source'])
            retained_state[project][node]=deep_copy({k:a[k] for k in ['states','verification','acceptance','provision','unresolved_edges','stale_reasons','relations','owners']})
            if 'kind' in a['source']:
                retained_state[project][node]['kind']=deep_copy(a['source']['kind'])
            gaps[project][node]=[axis for axis,allowed in axes.items() if a.get('states',{}).get(axis,{}).get('state')!=allowed[0]]
    # Same-side target ID collisions are alias violations on both nodes.
    for side,root in [('actual',data['projects']),('context',data['context']['projects'])]:
        buckets={}
        for project in projects:
            for node in nodes:
                tid=root[project][node].get('source',{}).get('target_id')
                if known(tid): buckets.setdefault(tid,[]).append((project,node))
        for colliding in buckets.values():
            if len(colliding)>1:
                for project,node in colliding:
                    add('identity_aliased',pointer(side,project,node,'source','target_id'))
                    node_corr[project][node]['source']='violation'
    claim=data.get('whole_completion_claim')
    if claim is True:add('whole_completion_forbidden','/whole_completion_claim')
    elif claim is not False:add('whole_claim_unknown','/whole_completion_claim')
    rank={'corresponding':0,'unknown':1,'violation':2}
    values=[x for p in projects for n in nodes for x in node_corr[p][n].values()]
    if claim is True: values.append('violation')
    elif claim is not False: values.append('unknown')
    highest=values[0]
    for value in values[1:]:
        if rank[value]>rank[highest]: highest=value
    condition={'corresponding':'trace_material_corresponding','unknown':'trace_material_unknown','violation':'trace_material_violation'}[highest]
    findings=route_failure(findings, return_owner)
    return {'condition':condition,'node_correspondence':node_corr,'retained_source_records':retained_source,'retained_state_trace':retained_state,'observed_gap_axes':gaps,'findings':findings,'actual_state_updated':False,'actual_acceptance_created':False,'actual_release_authorized':False,'whole_portfolio_complete':False,'operation_effect':'none'}

def evaluate_portfolio_selected(input, diagnostic_contract, *supplied_targets):
    return _evaluate_portfolio_selected_core(input, diagnostic_contract, supplied_targets, None)

def _evaluate_portfolio_selected_core(input, diagnostic_contract, supplied_targets, origin_association):
    # 0 supplied targetsはselected専用entrypointのAbsent。Noneはpresent null。
    if len(supplied_targets)>1:
        raise ValueError('selected targets引数は最大1件')
    targets_presence='absent' if not supplied_targets else 'null' if supplied_targets[0] is None else 'present'
    targets=supplied_targets[0] if targets_presence!='absent' else None
    rules=diagnostic_contract
    return_owner='portfolio-trace-owner'
    axes=rules['state_axes']
    facets=rules['facet_order']
    source_fields=rules['source_fields']
    receipt_fields=rules['receipt_fields']
    rank={'corresponding':0,'unknown':1,'violation':2}
    findings=[]
    node_corr={}
    retained_source={}
    retained_state={}
    gaps={}
    def as_map(value):
        return value if isinstance(value,dict) else {}
    def known(value):
        return isinstance(value,str) and len(value)>0
    def token(value):
        return str(value).replace('~','~0').replace('/','~1')
    def pointer(side,project,node,*parts):
        prefix='/projects/' if side=='actual' else '/context/projects/'
        return prefix+token(project)+'/'+token(node)+''.join('/'+token(part) for part in parts)
    def add(code,ptr):
        findings.append({'code':code,'pointer':ptr,'return_owner':return_owner})
    def locate(root,path,prefix):
        cursor=root
        ptr=prefix
        for key in path:
            if not isinstance(cursor,dict):
                return {'present':False,'value':None,'pointer':ptr}
            ptr=ptr+'/'+token(key)
            if key not in cursor:
                return {'present':False,'value':None,'pointer':ptr}
            cursor=cursor[key]
        return {'present':True,'value':cursor,'pointer':ptr}
    def map_value(located):
        return as_map(located['value'])
    def valid_record(located):
        return located['present'] and isinstance(located['value'],dict)
    def mark(project,node,facet,state):
        old=node_corr[project][node][facet]
        if rank[state]>rank[old]:
            node_corr[project][node][facet]=state
    def classify_set(value,ptr,allow_empty):
        if not isinstance(value,list) or any(not known(item) for item in value) or len(set(value))!=len(value):
            return None
        if not value and not allow_empty:
            return None
        return set(value)
    actual_projects=map_value(locate(input,['projects'],''))
    context_projects=map_value(locate(input,['context','projects'],''))
    selected_projects_location=locate(targets,['projects'],'/targets')
    selected_projects=map_value(selected_projects_location)
    def compare_selected_node(project, node, actual, context, declared):
        return compare_node_material(project,node,actual,context,rules,declared,as_map(context_projects.get(project)))
    # R12/R17: 選択のprovenanceとproject集合はraw target引数だけから読む。
    provenance_unknown=False
    for field in ['selection_source_ref','selection_source_revision','selection_source_digest']:
        location=locate(targets,[field],'/targets')
        if not location['present'] or not known(location['value']):
            add('field_unknown',location['pointer'])
            provenance_unknown=True
    if not valid_record(selected_projects_location):
        add('field_unknown',selected_projects_location['pointer'])
    identities=set()
    empty_nodes=[]
    for project in sorted(selected_projects):
        project_location=locate(targets,['projects',project],'/targets')
        project_target=map_value(project_location)
        if not valid_record(project_location):
            add('field_unknown',project_location['pointer'])
            continue
        if known(project_target.get('project_id')):
            identities.add(project_target['project_id'])
        else:
            location=locate(targets,['projects',project,'project_id'],'/targets')
            add('field_unknown',location['pointer'])
        nodes_location=locate(targets,['projects',project,'nodes'],'/targets')
        if not valid_record(nodes_location):
            add('field_unknown',nodes_location['pointer'])
        elif not nodes_location['value']:
            empty_nodes.append(nodes_location['pointer'])
    if valid_record(selected_projects_location) and len(identities)<2:
        add('field_unknown','/targets/projects')
    project_keys=sorted(set(list(actual_projects)+list(context_projects)+list(selected_projects)))
    for project in project_keys:
        actual_nodes=as_map(actual_projects.get(project))
        context_nodes=as_map(context_projects.get(project))
        project_target=as_map(selected_projects.get(project))
        selected_nodes=as_map(project_target.get('nodes'))
        node_corr[project]={}
        # R15: 存在しないactual projectの保持entryを作らない。
        if project in actual_projects and isinstance(actual_projects[project],dict):
            retained_source[project]={}
            retained_state[project]={}
            gaps[project]={}
        node_keys=sorted(set(list(actual_nodes)+list(context_nodes)+list(selected_nodes)))
        for node in node_keys:
            actual_location=locate(input,['projects',project,node],'')
            context_location=locate(input,['context','projects',project,node],'')
            selection_location=locate(targets,['projects',project,'nodes',node],'/targets')
            a=actual_location['value']
            c=context_location['value']
            target=map_value(selection_location)
            selected=valid_record(selection_location)
            both=valid_record(actual_location) and valid_record(context_location)
            node_corr[project][node]={facet:'corresponding' if selected and both else 'unknown' for facet in facets}
            if not selected:
                add('field_unknown',selection_location['pointer'])
                if node in actual_nodes and not valid_record(actual_location):
                    add('field_unknown',actual_location['pointer'])
            else:
                for location in [actual_location,context_location]:
                    if not valid_record(location):
                        add('field_unknown',location['pointer'])
                if both:
                    compared=compare_selected_node(project,node,a,c,target.get('kind'))
                    node_corr[project][node]=compared['facet_results']
                    for finding in compared['findings']:
                        findings.append(finding)
                if provenance_unknown:
                    mark(project,node,'source','unknown')
                project_axes=rules['selected_target_contract']['identity_and_binding']['project_axes']
                node_axes=rules['selected_target_contract']['identity_and_binding']['node_axes']
                for fields,selection,path in [(project_axes,project_target,['projects',project]),(node_axes,target,['projects',project,'nodes',node])]:
                    for field in fields:
                        value=selection.get(field)
                        is_kind=field=='kind'
                        is_known=known(value) and (not is_kind or value in {'unit','connection','composite'})
                        if not is_known:
                            location=locate(targets,path+[field],'/targets')
                            add('kind_unknown' if is_kind else 'field_unknown',location['pointer'])
                            mark(project,node,'source','unknown')
                        else:
                            for side,location in [('actual',actual_location),('context',context_location)]:
                                if valid_record(location):
                                    source=as_map(location['value'].get('source'))
                                    actual_value=source.get(field)
                                    p=pointer(side,project,node,'source',field)
                                    if not known(actual_value) or (is_kind and actual_value not in {'unit','connection','composite'}):
                                        add('kind_unknown' if is_kind else 'field_unknown',p)
                                        mark(project,node,'source','unknown')
                                    elif actual_value!=value:
                                        add('kind_conflict' if is_kind else 'field_conflict',p)
                                        mark(project,node,'source','violation')
            # 明示operandによる局所source join。both/selected枝の外、旧retention前。
            if origin_association is not None and project == origin_association['project_key'] and node == origin_association['node_key']:
                mark(project,node,'source',origin_association['source_disposition'])
                findings.extend(deep_copy(origin_association['findings']))
            # R11/R15: actualの元memberだけをdeepcopyし、contextから埋めない。
            if node in actual_nodes and isinstance(a,dict):
                if 'source' in a:
                    retained_source[project][node]=deep_copy(a['source'])
                retained_state[project][node]=deep_copy({key:a[key] for key in ['states','verification','acceptance','provision','unresolved_edges','stale_reasons','relations','owners'] if key in a})
                if isinstance(a.get('source'),dict) and 'kind' in a['source']:
                    retained_state[project][node]['kind']=deep_copy(a['source']['kind'])
                if 'states' in a:
                    gaps[project][node]=[axis for axis,allowed in axes.items() if as_map(as_map(a['states']).get(axis)).get('state')!=allowed[0]]
    # R02/R09: selection外も含む全observed node。sideをまたいだaliasは作らない。
    for side,projects in [('actual',actual_projects),('context',context_projects)]:
        buckets={}
        for project in sorted(projects):
            for node in sorted(as_map(projects[project])):
                raw=projects[project][node]
                if not isinstance(raw,dict):
                    continue
                tid=as_map(raw.get('source')).get('target_id')
                if known(tid):
                    buckets.setdefault(tid,[]).append((project,node))
                if side=='actual':
                    for field in ['from_unit_success','from_pr_ci_plan','whole_node_complete']:
                        value=as_map(raw.get('claims')).get(field)
                        if value is True:
                            add('inferred_completion_forbidden',pointer(side,project,node,'claims',field))
                            mark(project,node,'boundary','violation')
                        elif value is not False:
                            add('claim_unknown',pointer(side,project,node,'claims',field))
                            mark(project,node,'boundary','unknown')
        for colliding in buckets.values():
            if len(colliding)>1:
                for project,node in colliding:
                    add('identity_aliased',pointer(side,project,node,'source','target_id'))
                    mark(project,node,'source','violation')
    if not any(node_corr[project] for project in node_corr) and selected_projects and len(empty_nodes)==len(selected_projects):
        for ptr in empty_nodes:
            add('result_unknown',ptr)
    claim=as_map(input).get('whole_completion_claim')
    if claim is True:
        add('whole_completion_forbidden','/whole_completion_claim')
    elif claim is not False:
        add('whole_claim_unknown','/whole_completion_claim')
    values=[value for project in node_corr.values() for node in project.values() for value in node.values()]
    # nodeを持たない選択domainの局所診断もaggregateの理由として保持する。
    code_rank={item['code']:item['disposition'] for item in rules['codes']}
    for finding in findings:
        values.append(code_rank[finding['code']])
    highest='unknown' if not values else 'corresponding'
    for value in values:
        if rank[value]>rank[highest]:
            highest=value
    condition={'corresponding':'trace_material_corresponding','unknown':'trace_material_unknown','violation':'trace_material_violation'}[highest]
    return {'condition':condition,'node_correspondence':node_corr,'retained_source_records':retained_source,'retained_state_trace':retained_state,'observed_gap_axes':gaps,'findings':route_failure(findings,return_owner),'actual_state_updated':False,'actual_acceptance_created':False,'actual_release_authorized':False,'whole_portfolio_complete':False,'operation_effect':'none'}


def capture_source_member(root, tokens, prefix=''):
    def escape(token):
        return token.replace('~', '~0').replace('/', '~1')
    requested = prefix + ''.join('/' + escape(token) for token in tokens)
    reached = prefix
    value = root
    for token in tokens:
        if not isinstance(value, dict):
            return {'requested_pointer': requested, 'reached_pointer': reached,
                    'availability': 'blocked', 'value': deep_copy(value)}
        reached += '/' + escape(token)
        if token not in value:
            return {'requested_pointer': requested, 'reached_pointer': reached,
                    'availability': 'absent'}
        value = value[token]
    return {'requested_pointer': requested, 'reached_pointer': reached,
            'availability': 'present', 'value': deep_copy(value)}


def locate_failure_source(finding):
    pointer = finding['pointer']
    raw = pointer[1:].split('/') if pointer.startswith('/') else []
    valid = pointer == '' or pointer.startswith('/')
    for token in raw:
        cursor = 0
        while cursor < len(token):
            if token[cursor] == '~':
                if cursor + 1 >= len(token) or token[cursor + 1] not in '01':
                    valid = False
                    break
                cursor += 2
            else:
                cursor += 1
    tokens = [token.replace('~1', '/').replace('~0', '~') for token in raw]
    side = 'unbound'
    offset = None
    if valid and tokens[:2] == ['context', 'projects']:
        side, offset = 'context', 2
    elif valid and tokens[:1] == ['projects']:
        side, offset = 'actual', 1
    elif valid and tokens[:2] == ['targets', 'projects']:
        side, offset = 'selected', 2
    if offset is not None and len(tokens) > offset:
        project = tokens[offset]
        tail = tokens[offset + 1:]
        if side != 'selected' and tail:
            return {'kind': 'node', 'project_key': project,
                    'node_key': tail[0], 'finding_side': side}
        if side == 'selected' and len(tail) >= 2 and tail[0] == 'nodes':
            return {'kind': 'node', 'project_key': project,
                    'node_key': tail[1], 'finding_side': side}
        return {'kind': 'project', 'project_key': project, 'finding_side': side}
    return {'kind': 'unbound', 'finding_side': side,
            'reason': 'container_or_non_locator_pointer'}


def compare_failure_source_materials(actual, context, selected):
    project_axes = ['project_id', 'requirement_id', 'requirement_revision',
                    'scope', 'harness_contract_revision']
    node_axes = ['target_id', 'target_revision', 'target_digest', 'kind',
                 'source_ref', 'source_revision']
    source_axes = project_axes + node_axes + ['difference_ref', 'operation_record_ref']
    def read_source(capture, field):
        if capture['availability'] == 'present' and isinstance(capture['value'], dict):
            return capture['value'].get(field)
        return None
    def compare(left, right, field):
        if field == 'kind':
            allowed = ['unit', 'connection', 'composite']
            known = isinstance(left, str) and isinstance(right, str) and left in allowed and right in allowed
        else:
            known = isinstance(left, str) and bool(left) and isinstance(right, str) and bool(right)
        if not known:
            return 'unknown'
        return 'material_corresponding' if left == right else 'material_conflict'
    def selected_value(field):
        capture = selected['project_axes' if field in project_axes else 'node_axes'][field]
        return capture['value'] if capture['availability'] == 'present' else None
    return {
        'kind': 'node',
        'actual_context': {field: compare(read_source(actual, field), read_source(context, field), field)
                           for field in source_axes},
        'actual_selected': {field: compare(read_source(actual, field), selected_value(field), field)
                            for field in project_axes + node_axes},
        'context_selected': {field: compare(read_source(context, field), selected_value(field), field)
                             for field in project_axes + node_axes}}


def bind_portfolio_failure_source_candidates(evaluation):
    input = evaluation['input']
    project_axes = ['project_id', 'requirement_id', 'requirement_revision',
                    'scope', 'harness_contract_revision']
    node_axes = ['target_id', 'target_revision', 'target_digest', 'kind',
                 'source_ref', 'source_revision']
    candidates = []
    for finding in evaluation['trace_material']['findings']:
        locator = locate_failure_source(finding)
        materials = {'kind': 'unbound'}
        comparisons = {'kind': 'not_node_bound'}
        if locator['kind'] in ['node', 'project']:
            project = locator['project_key']
            selected_project = {field: capture_source_member(evaluation, ['targets', 'projects', project, field])
                                for field in project_axes}
            if locator['kind'] == 'project':
                materials = {'kind': 'project', 'selected_project_axes': selected_project}
            else:
                node = locator['node_key']
                actual_tokens = ['projects', project, node]
                context_tokens = ['context', 'projects', project, node]
                actual = {'node_record': capture_source_member(input, actual_tokens),
                          'source': capture_source_member(input, actual_tokens + ['source']),
                          'owners': capture_source_member(input, actual_tokens + ['owners'])}
                context = {'node_record': capture_source_member(input, context_tokens),
                           'source': capture_source_member(input, context_tokens + ['source']),
                           'owners': capture_source_member(input, context_tokens + ['owners'])}
                selected = {'project_axes': selected_project,
                            'node_axes': {field: capture_source_member(evaluation, ['targets', 'projects', project, 'nodes', node, field])
                                          for field in node_axes}}
                materials = {'kind': 'node', 'actual': actual, 'context': context, 'selected': selected}
                comparisons = compare_failure_source_materials(actual['source'], context['source'], selected)
        candidates.append({'finding': deep_copy(finding), 'locator': locator,
                           'material_sources': materials, 'comparisons': comparisons,
                           'recipient_qualification': 'not_established', 'actual_delivery': False})
    return candidates


def evaluate_portfolio_with_source_candidates(input, diagnostic_contract, *supplied_targets):
    if len(supplied_targets) > 1:
        raise ValueError('selected targets引数は最大1件')
    trace = evaluate_portfolio_selected(input, diagnostic_contract, *supplied_targets)
    evaluation = {'input': input, 'trace_material': trace}
    if supplied_targets:
        evaluation['targets'] = supplied_targets[0]
    return {'trace_material': trace,
            'failure_source_candidates': bind_portfolio_failure_source_candidates(evaluation),
            'operation_effect': 'none'}

