def typed_json_equal(left, right):
    """OS015 primitive equal: bool!=number、missingはmember集合で区別。"""
    if isinstance(left, dict) or isinstance(right, dict):
        return (isinstance(left, dict) and isinstance(right, dict)
                and left.keys() == right.keys()
                and all(typed_json_equal(left[key], right[key]) for key in left))
    if isinstance(left, list) or isinstance(right, list):
        return (isinstance(left, list) and isinstance(right, list)
                and len(left) == len(right)
                and all(typed_json_equal(a, b) for a, b in zip(left, right)))
    if type(left) is bool or type(right) is bool:
        return type(left) is bool and type(right) is bool and left == right
    if isinstance(left, (int, float)) and isinstance(right, (int, float)):
        return left == right
    return type(left) is type(right) and left == right


def material_type_formed(value, declaration='MaterialInput'):
    """既存OS015閉型だけの型形成。値の意味/資格を検査しない。"""
    if declaration == 'JsonValue':
        return True  # 本関数の入力domainはJSONValue。
    if isinstance(declaration, str):
        declaration = OS015_INPUT_TYPES[declaration]
    kind = declaration['kind']
    if kind == 'non_object_json':
        return not isinstance(value, dict)
    if kind == 'union':
        return any(material_type_formed(value, variant)
                   for variant in declaration['variants'])
    if kind == 'record':
        fields = declaration['fields']
        return (isinstance(value, dict) and value.keys() == fields.keys()
                and all(material_type_formed(value[key], field)
                        for key, field in fields.items()))
    raise ValueError('未宣言OS015入力型')


def normalise_origin_capture_view(envelope):
    view = {'selection': {}}
    for member in ['os015_raw_input', 'os015_typed_input']:
        if envelope[member]['state'] == 'Present':
            view[member] = deep_copy(envelope[member]['value'])
    args = envelope['ordinary_call']['supplied_targets']
    if args:
        view['existing_selected_targets'] = deep_copy(args[0])
    selection = envelope['selection']
    if selection['state'] == 'Selected':
        for name, field in [('target_key', 'os015_target_key'),
                            ('project_key', 'portfolio_project_key'),
                            ('node_key', 'portfolio_node_key')]:
            view['selection'][name] = deep_copy(selection[field])
    elif selection['state'] == 'SelectedButNotProduced':
        for name in ['target_key', 'project_key', 'node_key']:
            if selection[name]['state'] == 'Present':
                view['selection'][name] = deep_copy(selection[name]['value'])
    return view


def compare_os015_origin_project_axes(project_key, node_key, produced,
                                      origin_captures, project_captures):
    def known_capture(capture):
        return (capture['availability'] == 'present'
                and isinstance(capture['value'], str) and bool(capture['value']))
    pointer = '/targets/projects/' + project_key.replace('~', '~0').replace('/', '~1')
    pointer += '/nodes/' + node_key.replace('~', '~0').replace('/', '~1')
    axes = {}
    findings = []
    rank = {'corresponding': 0, 'unknown': 1, 'violation': 2}
    disposition = 'corresponding'
    for axis in ['scope', 'requirement_revision']:
        origin = origin_captures[axis]
        selected = project_captures[axis]
        if not produced or not known_capture(origin) or not known_capture(selected):
            state = 'unknown'
        elif origin['value'] == selected['value']:
            state = 'corresponding'
        else:
            state = 'violation'
        finding = None
        if state != 'corresponding':
            finding = {'code': 'field_conflict' if state == 'violation' else 'field_unknown',
                       'pointer': pointer, 'return_owner': 'portfolio-trace-owner'}
            findings.append(deep_copy(finding))
        axes[axis] = {'operand_state': 'produced' if produced else 'not_produced',
                      'origin': deep_copy(origin), 'selected_project': deep_copy(selected),
                      'disposition': state, 'finding_key': finding}
        if rank[state] > rank[disposition]:
            disposition = state
    return {'project_key': project_key, 'node_key': node_key,
            'source_disposition': disposition, 'axis_observations': axes,
            'findings': findings}


def evaluate_os015_origin_call(envelope):
    """InputEnvelope -> PrivateReturn。外部I/O/期待/recipeへの依存なし。"""
    call = envelope['ordinary_call']
    if call['callee'] != 'evaluate_portfolio_with_source_candidates':
        raise ValueError('未宣言ordinary callee')
    args = call['supplied_targets']
    if len(args) > 1:
        raise ValueError('selected targets引数は最大1件')
    selection = envelope['selection']
    original = {'os016_input': deep_copy(call['input']),
                'original_targets_args': deep_copy(args),
                'os015_raw_input': deep_copy(envelope['os015_raw_input']),
                'os015_typed_input': deep_copy(envelope['os015_typed_input']),
                'os015_call_result': deep_copy(envelope['os015_call_result']),
                'selection': deep_copy(selection)}
    result = {'original_materials': original, 'effective_targets': {'state': 'Absent'},
              'origin_selection': deep_copy(selection), 'projection_status': 'NotProduced',
              'source_bound_trace': {'state': 'NotProduced'},
              'origin_association_observations': {'state': 'NotRequested'},
              'operation_effect': 'none'}
    if selection['state'] == 'NotSelected':
        result['projection_status'] = 'NotSelected'
        if args:
            result['effective_targets'] = {'state': 'Present', 'value': deep_copy(args[0])}
        result['source_bound_trace'] = {
            'state': 'Returned',
            'value': evaluate_portfolio_with_source_candidates(
                call['input'], call['diagnostic_contract'], *args)}
        return result
    view = normalise_origin_capture_view(envelope)
    keys = view['selection']
    locator_keys_known = (isinstance(keys.get('project_key'), str)
                          and isinstance(keys.get('node_key'), str))
    binding = {'state': 'NotRequested'}
    if locator_keys_known:
        project = keys['project_key']
        node = keys['node_key']
        located = capture_source_member(
            view, ['existing_selected_targets', 'projects', project, 'nodes', node])
        binding = {'state': 'Captured', 'value': located}
    bound = (binding['state'] == 'Captured'
             and binding['value']['availability'] == 'present'
             and isinstance(binding['value']['value'], dict))
    if not bound:
        result['origin_association_observations'] = {
            'state': 'NotProduced',
            'selection_captures': {
                'target_key': capture_source_member(view, ['selection', 'target_key']),
                'project_key': capture_source_member(view, ['selection', 'project_key']),
                'node_key': capture_source_member(view, ['selection', 'node_key']),
                'targets_binding': binding},
            'origin_captures': {
                'raw_input': capture_source_member(view, ['os015_raw_input']),
                'typed_input': capture_source_member(view, ['os015_typed_input'])},
            'reason': 'locator_unbound'}
        return result
    raw = envelope['os015_raw_input']
    typed = envelope['os015_typed_input']
    produced = (selection['state'] == 'Selected'
                and raw['state'] == 'Present' and typed['state'] == 'Present'
                and material_type_formed(typed['value'])
                and typed_json_equal(raw['value'], typed['value']))
    effective = deep_copy(args[0])
    target = effective['projects'][project]['nodes'][node]
    for origin_field, selected_field in [
            ('target_id', 'target_id'), ('target_revision', 'target_revision'),
            ('target_digest', 'target_digest'), ('source_id', 'source_ref'),
            ('source_revision', 'source_revision')]:
        if produced:
            target[selected_field] = deep_copy(
                typed['value']['records'][keys['target_key']]['source'][origin_field])
        else:
            target.pop(selected_field, None)
    origin_captures = {}
    project_captures = {}
    for axis in ['scope', 'requirement_revision']:
        if isinstance(keys.get('target_key'), str):
            origin_captures[axis] = capture_source_member(
                view, ['os015_raw_input', 'records', keys['target_key'], 'source', axis])
        else:
            origin_captures[axis] = capture_source_member(view, ['selection', 'target_key'])
        project_captures[axis] = capture_source_member(
            view, ['existing_selected_targets', 'projects', project, axis])
    comparison = compare_os015_origin_project_axes(
        project, node, produced, origin_captures, project_captures)
    trace = _evaluate_portfolio_selected_core(
        call['input'], call['diagnostic_contract'], (effective,), comparison)
    evaluation = {'input': call['input'], 'trace_material': trace, 'targets': effective}
    source_bound = {'trace_material': trace,
                    'failure_source_candidates': bind_portfolio_failure_source_candidates(evaluation),
                    'operation_effect': 'none'}
    result['effective_targets'] = {'state': 'Present', 'value': effective}
    result['projection_status'] = 'Produced' if produced else 'NotProduced'
    result['source_bound_trace'] = {'state': 'Returned', 'value': source_bound}
    result['origin_association_observations'] = {'state': 'Compared', 'value': comparison}
    return result
